-- The Angel Arena item set: ninety-nine items that share this one script.
--
-- Items are defined in scripts/npc/items/arena/arena_items.txt, which is generated by
-- tools/items/build_arena_items.py. This file reads those definitions and creates one Lua
-- class per item, so adding an item never means writing a new script:
--   "AbilityValues"    every number the item uses
--   "ArenaMechanics"   passive effects, implemented in arena_modifiers.lua
--   "ArenaActive"      the effect of clicking the item
--   "ArenaConsume"     the effect of a single-use tome, potion or flask
-- What each effect looks and sounds like is in arena_fx.lua.

local SCRIPT_FILE = "items/arena/arena_items"
local FLIGHT_HEIGHT = 140 -- how far a flying hero is lifted off the ground

require("items/arena/arena_data")
require("items/arena/arena_fx")
require("items/arena/arena_modifiers")

local function Deal(victim, attacker, ability, amount)
    ApplyDamage({ victim = victim, attacker = attacker, ability = ability, damage = amount, damage_type = DAMAGE_TYPE_MAGICAL })
end

local function UnitsAround(caster, radius, team)
    return FindUnitsInRadius(caster:GetTeamNumber(), caster:GetAbsOrigin(), nil, radius, team,
        DOTA_UNIT_TARGET_HERO + DOTA_UNIT_TARGET_BASIC, DOTA_UNIT_TARGET_FLAG_NONE, FIND_ANY_ORDER, false)
end

------------------------------------------------------------------------------------ actives

local actives = {}

function actives.heal(item, caster, v)
    local allies = UnitsAround(caster, v.active_radius, DOTA_UNIT_TARGET_TEAM_FRIENDLY)
    ArenaFx.Heal(caster, allies)
    for _, ally in ipairs(allies) do
        ally:Heal(v.active_heal, item)
    end
end

function actives.flight(item, caster, v)
    caster:EmitSound("DOTA_Item.ForceStaff.Activate")
    caster:AddNewModifier(caster, item, "modifier_arena_flight", { duration = v.active_duration })
end

function actives.rage(item, caster, v)
    caster:EmitSound("hero_bloodseeker.bloodRage")
    caster:AddNewModifier(caster, item, "modifier_arena_rage", { duration = v.active_duration })
end

function actives.nova(item, caster, v)
    ArenaFx.Nova(caster, v.active_radius)
    for _, enemy in ipairs(UnitsAround(caster, v.active_radius, DOTA_UNIT_TARGET_TEAM_ENEMY)) do
        Deal(enemy, caster, item, v.active_damage)
        enemy:AddNewModifier(caster, item, "modifier_arena_burning", { duration = v.burn_duration, dps = v.burn_dps })
    end
end

-- A single-target strike. The staffs cast it as a lance of sunlight; the war hammer, which
-- also bashes, calls down a bolt.
function actives.smite(item, caster, v)
    local target = item:GetCursorTarget()
    if not target or target:TriggerSpellAbsorb(item) then
        return
    end
    if v.bash_chance then
        ArenaFx.Verdict(target)
    else
        ArenaFx.Sunlance(caster, target, v.active_damage)
    end
    if v.active_stun > 0 then
        target:AddNewModifier(caster, item, "modifier_stunned",
            { duration = v.active_stun * (1 - target:GetStatusResistance()) })
    end
    Deal(target, caster, item, v.active_damage)
end

function actives.shield(item, caster, v)
    caster:Purge(false, true, false, true, true)
    caster:AddNewModifier(caster, item, "modifier_arena_void_shell", { duration = v.active_duration })
end

--------------------------------------------------------------------------------- consumables

-- Permanent bonuses from tomes live in a modifier whose stack count is the total granted, so
-- the bonus needs no ability once the tome is gone. Armour is stored in tenths.
local function Study(caster, modifier, amount)
    local bonus = caster:FindModifierByName(modifier) or caster:AddNewModifier(caster, nil, modifier, {})
    bonus:SetStackCount(bonus:GetStackCount() + amount)
    caster:CalculateStatBonus(true)
end

local consumables = {}

function consumables.tome_health(caster, v) Study(caster, "modifier_arena_tome_health", v.tome_health) end
function consumables.tome_armor(caster, v) Study(caster, "modifier_arena_tome_armor", math.floor(v.tome_armor * 10 + 0.5)) end
function consumables.tome_damage(caster, v) Study(caster, "modifier_arena_tome_damage", v.tome_damage) end

function consumables.tome_level(caster, v)
    for _ = 1, v.tome_levels do
        caster:HeroLevelUp(true)
    end
end

function consumables.tome_stats(caster, v)
    caster:ModifyStrength(v.tome_all_stats)
    caster:ModifyAgility(v.tome_all_stats)
    caster:ModifyIntellect(v.tome_all_stats)
end

function consumables.potion_heal(caster, v, item)
    caster:Heal(caster:GetMaxHealth() * v.potion_heal_pct / 100, item)
end

function consumables.potion_mana(caster, v)
    caster:GiveMana(caster:GetMaxMana() * v.potion_mana_pct / 100)
end

function consumables.potion_buff(caster, v, item)
    caster:AddNewModifier(caster, nil, "modifier_arena_potion", {
        duration = v.potion_duration,
        texture = item:GetAbilityTextureName(),
        damage = v.buff_damage or 0,
        attack_speed = v.buff_attack_speed or 0,
        armor = v.buff_armor or 0,
        magic_resistance = v.buff_magic_resistance or 0,
    })
end

function consumables.potion_ember(caster, v)
    caster:AddNewModifier(caster, nil, "modifier_arena_ember",
        { duration = v.potion_duration, dps = v.ember_dps, radius = v.ember_radius })
end

local function Consume(item, kind)
    local caster = item:GetCaster()
    local tome = string.sub(kind, 1, 4) == "tome"
    if tome and not caster:IsRealHero() then
        return -- couriers and illusions cannot learn
    end
    consumables[kind](caster, ArenaItems.Values(item), item)
    if tome then
        ArenaFx.Tome(caster)
    else
        ArenaFx.Potion(caster, kind == "potion_mana")
    end
    if item:GetCurrentCharges() > 1 then
        item:SetCurrentCharges(item:GetCurrentCharges() - 1)
    else
        caster:RemoveItem(item)
    end
end

--------------------------------------------------------------------------------- item classes

for name, definition in pairs(ArenaItems.definitions) do
    local item = class({})
    local consume = definition.ArenaConsume
    local active = definition.ArenaActive

    function item:Precache(context)
        ArenaFx.Precache(context)
    end

    if consume then
        function item:OnSpellStart() Consume(self, consume) end
    else
        function item:GetIntrinsicModifierName() return "modifier_arena_item" end
        if active then
            function item:OnSpellStart() actives[active](self, self:GetCaster(), ArenaItems.Values(self)) end
        end
    end

    _G[name] = item
end

---------------------------------------------------------------------------- timed self buffs

local function Link(name)
    local modifier = class({})
    function modifier:IsPurgable() return false end
    _G[name] = modifier
    LinkLuaModifier(name, SCRIPT_FILE, LUA_MODIFIER_MOTION_NONE)
    return modifier
end

-- Flight lifts the hero off the ground and lets it cross anything.
local flight = Link("modifier_arena_flight")

function flight:OnCreated()
    self.values = ArenaItems.Values(self:GetAbility())
    if IsServer() then
        self.wings = self.wings or ArenaFx.Wings(self:GetParent())
    end
end

flight.OnRefresh = flight.OnCreated

function flight:CheckState() return { [MODIFIER_STATE_FLYING] = true } end
function flight:DeclareFunctions() return { MODIFIER_PROPERTY_MOVESPEED_BONUS_PERCENTAGE, MODIFIER_PROPERTY_VISUAL_Z_DELTA } end
function flight:GetModifierMoveSpeedBonus_Percentage() return self.values.active_move_speed or 0 end
function flight:GetVisualZDelta() return FLIGHT_HEIGHT end
function flight:OnDestroy()
    if IsServer() then
        ArenaFx.Stop(self.wings)
        -- Landing inside a cliff or a tree line would trap the hero.
        FindClearSpaceForUnit(self:GetParent(), self:GetParent():GetAbsOrigin(), true)
    end
end

local rage = Link("modifier_arena_rage")

function rage:OnCreated()
    self.values = ArenaItems.Values(self:GetAbility())
    if IsServer() then
        self.swirl = self.swirl or ArenaFx.Rage(self:GetParent())
    end
end

rage.OnRefresh = rage.OnCreated

function rage:OnDestroy()
    if IsServer() then
        ArenaFx.Stop(self.swirl)
    end
end

function rage:DeclareFunctions()
    return { MODIFIER_PROPERTY_ATTACKSPEED_BONUS_CONSTANT, MODIFIER_PROPERTY_PREATTACK_BONUS_DAMAGE }
end
function rage:GetModifierAttackSpeedBonus_Constant() return self.values.active_attack_speed or 0 end
function rage:GetModifierPreAttack_BonusDamage() return self.values.active_damage or 0 end
function rage:GetEffectName() return ArenaFx.BUFF.rage end

-- Absorbs damage until its pool runs out.
local shell = Link("modifier_arena_void_shell")

function shell:OnCreated()
    if IsServer() then
        self.remaining = ArenaItems.Values(self:GetAbility()).active_shield or 0
        self.bubble = self.bubble or ArenaFx.Shell(self:GetParent())
    end
end

shell.OnRefresh = shell.OnCreated

function shell:OnDestroy()
    if IsServer() then
        ArenaFx.Stop(self.bubble)
        ArenaFx.ShellBreak(self:GetParent())
    end
end

function shell:DeclareFunctions() return { MODIFIER_PROPERTY_TOTAL_CONSTANT_BLOCK } end

function shell:GetModifierTotal_ConstantBlock(event)
    if not IsServer() then
        return 0
    end
    local blocked = math.min(self.remaining, event.damage)
    self.remaining = self.remaining - blocked
    if self.remaining <= 0 then
        self:Destroy()
    end
    return blocked
end

-- A potion's item is destroyed as it is drunk, so its numbers travel in the creation table
-- and are sent on to the client, which needs them to show the changed stats.
local potion = Link("modifier_arena_potion")

function potion:OnCreated(data)
    if IsServer() then
        self.bonus = { damage = data.damage, attack_speed = data.attack_speed, armor = data.armor,
            magic_resistance = data.magic_resistance, texture = data.texture }
        self:SetHasCustomTransmitterData(true)
    end
end

potion.OnRefresh = potion.OnCreated

function potion:AddCustomTransmitterData() return self.bonus end
function potion:HandleCustomTransmitterData(data) self.bonus = data end

function potion:DeclareFunctions()
    return {
        MODIFIER_PROPERTY_PREATTACK_BONUS_DAMAGE,
        MODIFIER_PROPERTY_ATTACKSPEED_BONUS_CONSTANT,
        MODIFIER_PROPERTY_PHYSICAL_ARMOR_BONUS,
        MODIFIER_PROPERTY_MAGICAL_RESISTANCE_BONUS,
    }
end

function potion:GetModifierPreAttack_BonusDamage() return self.bonus and self.bonus.damage or 0 end
function potion:GetModifierAttackSpeedBonus_Constant() return self.bonus and self.bonus.attack_speed or 0 end
function potion:GetModifierPhysicalArmorBonus() return self.bonus and self.bonus.armor or 0 end
function potion:GetModifierMagicalResistanceBonus() return self.bonus and self.bonus.magic_resistance or 0 end
function potion:GetTexture() return self.bonus and self.bonus.texture end

-- The ember flask sets the ground around its drinker alight.
local ember = Link("modifier_arena_ember")

function ember:OnCreated(data)
    if IsServer() then
        self.dps = data.dps
        self.radius = data.radius
        self.ground = self.ground or ArenaFx.Scorched(self:GetParent(), data.radius)
        self:StartIntervalThink(1)
    end
end

ember.OnRefresh = ember.OnCreated

function ember:OnIntervalThink()
    local parent = self:GetParent()
    for _, enemy in ipairs(UnitsAround(parent, self.radius, DOTA_UNIT_TARGET_TEAM_ENEMY)) do
        Deal(enemy, parent, nil, self.dps)
    end
end

function ember:OnDestroy()
    if IsServer() then
        ArenaFx.Stop(self.ground)
    end
end

function ember:GetTexture() return "arena/ember_flask" end

------------------------------------------------------------------------- permanent tome bonuses

local function Tome(name, property, getter, scale, texture)
    local modifier = Link(name)
    function modifier:IsPermanent() return true end
    function modifier:RemoveOnDeath() return false end
    function modifier:GetTexture() return texture end
    function modifier:DeclareFunctions() return { property } end
    modifier[getter] = function(self) return self:GetStackCount() / scale end
end

Tome("modifier_arena_tome_health", MODIFIER_PROPERTY_HEALTH_BONUS, "GetModifierHealthBonus", 1, "arena/tome_vitality")
Tome("modifier_arena_tome_armor", MODIFIER_PROPERTY_PHYSICAL_ARMOR_BONUS, "GetModifierPhysicalArmorBonus", 10, "arena/tome_stoneskin")
Tome("modifier_arena_tome_damage", MODIFIER_PROPERTY_PREATTACK_BONUS_DAMAGE, "GetModifierPreAttack_BonusDamage", 1, "arena/tome_slaughter")
